import { Form } from '@/components/ui/form';
import { useFieldArray, useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { apiGet, apiPost } from '@/lib/axios/axios-utils';
import { endpoints } from '@/lib/axios/axios-global';
import { useEffect, useMemo, useState } from 'react';
import TimeInputForm from '@/components/forms/TimeInputForm';
import SelectInputForm from '@/components/forms/SelectInputForm';
import { toast } from 'sonner';
import MainHeading from '@/components/heading/MainHeading';
import DaysSwitchInputForm from '@/components/forms/DaysSwitchInputForm';
import TextInputForm from '@/components/forms/TextInputForm';
import { AddShiftFormValues, AddShiftSchema } from '../schemas/addShift/add-attendance-schema';
import { useNavigate } from 'react-router-dom';
import { shiftInfo } from '../../types/shift.types';
import Submission from './Submission';
import PlusIcon from '@/components/icons/popups/PlusIcon';
import { dayActive, normalizeTimeForInput, parseDelayRulesFromShift } from './shiftFormUtils';

const SHIFT_DAY_FIELD_KEYS = [
    'sunday',
    'monday',
    'tuesday',
    'wednesday',
    'thursday',
    'friday',
    'saturday',
] as const satisfies readonly (keyof AddShiftFormValues)[];

interface Props {
    shift?: shiftInfo | null;
}

export default function AddShiftForm({ shift }: Props) {
    const [error, setError] = useState<string | null>(null);
    const [loading, setLoading] = useState(false);
    const [_shifts, setShifts] = useState<{ name: string; value: string }[]>([]);
    const [_shiftsError, setShiftsError] = useState<string | null>(null);
    const [showSuccessPopup, setShowSuccessPopup] = useState(false);
    const [showCancelPopup, setShowCancelPopup] = useState(false);
    const navigate = useNavigate();

    const defaultValues = useMemo(
        () => ({
            name: shift?.name ?? '',
            type: shift?.type ?? '',
            sunday: dayActive(shift?.sunday),
            monday: dayActive(shift?.monday),
            tuesday: dayActive(shift?.tuesday),
            wednesday: dayActive(shift?.wednesday),
            thursday: dayActive(shift?.thursday),
            friday: dayActive(shift?.friday),
            saturday: dayActive(shift?.saturday),
            shift_start_time: normalizeTimeForInput(shift?.shift_start_time),
            shift_end_time: normalizeTimeForInput(shift?.shift_end_time),
            early_entry_time: normalizeTimeForInput(shift?.early_entry_time),
            early_exit_time: normalizeTimeForInput(shift?.early_exit_time),
            late_entry_time: normalizeTimeForInput(shift?.late_entry_time ?? undefined),
            late_exit_time: normalizeTimeForInput(shift?.late_exit_time ?? undefined),
            delayRules: parseDelayRulesFromShift(shift ?? null),
        }),
        [shift],
    );

    const form = useForm<AddShiftFormValues>({
        resolver: zodResolver(AddShiftSchema),
        defaultValues,
    });

    const { fields, append, remove } = useFieldArray({
        control: form.control,
        name: 'delayRules',
    });

    const formValues = form.watch();
    const allWorkDaysSelected = SHIFT_DAY_FIELD_KEYS.every((key) => formValues[key] === true);

    const onSubmit = async (data: AddShiftFormValues) => {
        setLoading(true);
        setError(null); // Clear previous errors
        const timeOrNull = (t: string) => (t.trim() === '' ? null : t);
        const { delayRules, ...rest } = data;
        const rules = delayRules.map((r) => ({
            minutes: Number.parseInt(String(r.delay_minutes), 10),
            amount: String(r.delay_calculation_method).trim(),
        }));

        let delay_minutes: number | string | null;
        let delay_calculation_method: string;

        if (rules.length === 1) {
            const m = rules[0].minutes;
            delay_minutes = Number.isFinite(m) ? m : null;
            delay_calculation_method = rules[0].amount;
        } else {
            delay_minutes = JSON.stringify(rules.map((r) => r.minutes));
            delay_calculation_method = JSON.stringify(rules.map((r) => r.amount));
        }

        const formatedData = {
            ...rest,
            sunday: data.sunday ? 1 : 0,
            monday: data.monday ? 1 : 0,
            tuesday: data.tuesday ? 1 : 0,
            wednesday: data.wednesday ? 1 : 0,
            thursday: data.thursday ? 1 : 0,
            friday: data.friday ? 1 : 0,
            saturday: data.saturday ? 1 : 0,
            early_entry_time: timeOrNull(data.early_entry_time),
            early_exit_time: timeOrNull(data.early_exit_time),
            late_entry_time: timeOrNull(data.late_entry_time),
            late_exit_time: timeOrNull(data.late_exit_time),
            delay_minutes,
            delay_calculation_method,
        };
        try {
            await apiPost({
                endpoint: shift ? endpoints.shifts.update + shift.id : endpoints.shifts.create,
                body: formatedData,
            });

            navigate('/human-resources/shifts');
            toast(`${shift ? 'تم تعديل الوردية بنجاح' : 'تم اضافة الوردية بنجاح'}`);
        } catch (error: any) {
            if (error.response?.data?.errors) {
                // Handle field-specific errors
                Object.entries(error.response.data.errors).forEach(([field, messages]) => {
                    form.setError(field as any, {
                        type: 'manual',
                        message: (messages as string[]).join(', '),
                    });
                });
            } else {
                // Handle generic error
                let errorMessage = 'حدث خطأ أثناء إرسال البيانات. يرجى المحاولة مرة أخرى.';
                if (error.response) {
                    errorMessage = error.response.data.msg || errorMessage;
                } else if (error.request) {
                    errorMessage = 'تعذر الاتصال بالخادم. يرجى التحقق من اتصالك بالإنترنت.';
                }
                setError(errorMessage);
            }
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        const fetchShifts = async () => {
            try {
                const response = await apiGet({ endpoint: endpoints.shifts.list });

                const list = Array.isArray(response.data.data) ? response.data.data : [];
                const options = list.map((s: { name: string }) => ({
                    name: s.name,
                    value: String(s.name),
                }));
                setShifts(options);
                setShiftsError(null);
                // setShowCancelPopup(true);
            } catch (error) {
                setShiftsError('Error fetching shifts. Please try again later.');
                // setShowSuccessPopup(false);
            }
        };

        fetchShifts();
    }, []);

    return (
        <>
            <Form {...form}>
                <form onSubmit={form.handleSubmit(onSubmit)} className="mt-6 mb-24">
                    {error && (
                        <div className="mb-4 p-4 bg-red-100 border border-red-400 text-red-700 rounded-lg">
                            <div className="flex justify-between items-center">
                                <span className="">{error}</span>
                                <button onClick={() => setError(null)} className="text-red-700 hover:text-red-900">
                                    ×
                                </button>
                            </div>
                        </div>
                    )}
                    <MainHeading text="تفاصيل الوردية" />
                    <div className="grid grid-cols-2 gap-x-12">
                        {/* <SearchableSelectInputForm
                            name="name"
                            placeholder="بحث عن اسم أو كود الوردية"
                            label="اسم الوردية"
                            options={shifts}
                            error={shiftsError}
                            data={true}
                        /> */}
                        <TextInputForm name="name" label="اسم الوردية" placeholder="ادخل اسم الوردية" />
                        <SelectInputForm
                            name="type"
                            options={[
                                { name: 'صباحى', value: 'am' },
                                { name: 'مسائى', value: 'pm' },
                            ]}
                            label="النوع"
                            placeholder="صباحى - مسائى"
                        />
                    </div>
                    <MainHeading text="أيام العمل" className="mt-6" />
                    <div className="mt-4 mb-4 flex justify-end">
                        <button
                            type="button"
                            onClick={() => {
                                const turnOn = !SHIFT_DAY_FIELD_KEYS.every((key) => form.getValues(key));
                                for (const key of SHIFT_DAY_FIELD_KEYS) {
                                    form.setValue(key, turnOn, { shouldDirty: true, shouldTouch: true });
                                }
                            }}
                            className="inline-flex items-center gap-2 rounded-md border border-primery-blue-200 bg-white px-3 py-2 text-sm font-medium text-primery-blue-600 hover:bg-primery-blue-50"
                        >
                            {allWorkDaysSelected ? 'إلغاء تحديد كل الأيام' : 'تحديد كل الأيام'}
                        </button>
                    </div>
                    <div className="mb-8 grid grid-cols-2 gap-6">
                        <DaysSwitchInputForm
                            className="w-full border border-[#E8E7EA] rounded-xl px-4 py-[26px] flex justify-between items-center"
                            name="sunday"
                            label="الأحد"
                        />
                        <DaysSwitchInputForm
                            className="w-full border border-[#E8E7EA] rounded-xl px-4 py-[26px] flex justify-between items-center"
                            name="monday"
                            label="الإثنين"
                        />
                        <DaysSwitchInputForm
                            className="w-full border border-[#E8E7EA] rounded-xl px-4 py-[26px] flex justify-between items-center"
                            name="tuesday"
                            label="الثلاثاء"
                        />
                        <DaysSwitchInputForm
                            className="w-full border border-[#E8E7EA] rounded-xl px-4 py-[26px] flex justify-between items-center"
                            name="wednesday"
                            label="الأربعاء"
                        />
                        <DaysSwitchInputForm
                            className="w-full border border-[#E8E7EA] rounded-xl px-4 py-[26px] flex justify-between items-center"
                            name="thursday"
                            label="الخميس"
                        />
                        <DaysSwitchInputForm
                            className="w-full border border-[#E8E7EA] rounded-xl px-4 py-[26px] flex justify-between items-center"
                            name="friday"
                            label="الجمعة"
                        />
                        <DaysSwitchInputForm
                            className="w-full border border-[#E8E7EA] rounded-xl px-4 py-[26px] flex justify-between items-center"
                            name="saturday"
                            label="السبت"
                        />
                    </div>
                    <MainHeading text="قواعد الحضور" className="mt-6" />
                    <div className="grid grid-cols-2 gap-x-6 gap-y-4">
                        <TimeInputForm
                            name="shift_start_time"
                            label="بداية الوردية"
                            placeholder="09:00"
                            className="flex flex-col"
                        />
                        <TimeInputForm
                            name="shift_end_time"
                            label="نهاية الوردية"
                            placeholder="17:00"
                            className="flex flex-col"
                        />
                        <TimeInputForm
                            name="early_entry_time"
                            label="بداية تسجيل الدخول"
                            placeholder="07:00"
                            className="flex flex-col"
                        />
                        <TimeInputForm
                            name="early_exit_time"
                            label="بداية تسجيل الخروج"
                            placeholder="15:00"
                            className="flex flex-col"
                        />
                        <TimeInputForm
                            name="late_entry_time"
                            label="فترة سماح التأخير:"
                            placeholder="15 د"
                            className="flex flex-col"
                        />
                        <TimeInputForm
                            name="late_exit_time"
                            label="فترة سماح التأخير (الخروج):"
                            placeholder="15 د"
                            className="flex flex-col"
                        />
                        <div className="col-span-2 space-y-3">
                            {fields.map((field, index) => (
                                <div key={field.id} className="flex flex-wrap items-end gap-2 sm:gap-3">
                                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-x-6 gap-y-3 flex-1 min-w-0">
                                        <TextInputForm
                                            name={`delayRules.${index}.delay_minutes`}
                                            type="number"
                                            label="التأخير (دقائق)"
                                            placeholder=""
                                            className="flex flex-col"
                                        />
                                        <TextInputForm
                                            name={`delayRules.${index}.delay_calculation_method`}
                                            type="number"
                                            label="قيمة التأخير (ر.س)"
                                            placeholder="ادخل قيمة التأخير"
                                            className="flex flex-col"
                                        />
                                    </div>
                                    {fields.length > 1 ? (
                                        <button
                                            type="button"
                                            onClick={() => remove(index)}
                                            className="h-10 w-10 shrink-0 rounded-md border border-primery-blue-200 text-primery-blue-600 hover:bg-primery-blue-50 text-xl leading-none mb-0.5"
                                            aria-label="حذف القاعدة"
                                        >
                                            ×
                                        </button>
                                    ) : null}
                                </div>
                            ))}
                            <button
                                type="button"
                                onClick={() => append({ delay_minutes: '', delay_calculation_method: '' })}
                                className="inline-flex items-center gap-2 rounded-md border border-primery-blue-200 bg-white px-3 py-2 text-sm font-medium text-primery-blue-600 hover:bg-primery-blue-50"
                            >
                                <PlusIcon />
                                إضافة قاعدة تأخير
                            </button>
                        </div>
                    </div>

                    <div className="flex flex-row justify-end gap-4 mt-6">
                        {/* <SecondaryButton
                            type="button"
                            className="text-base leading-5 tracking-normal !py-4 !px-16 bg-red-error-50 text-red-error-600 hover:text-white-blue-50 hover:bg-red-error-600  font-medium"
                        >
                            إلغاء
                        </SecondaryButton> */}
                        <Submission
                            shift={shift}
                            loading={loading}
                            setShowSuccessPopup={setShowSuccessPopup}
                            setShowCancelPopup={setShowCancelPopup}
                            showSuccessPopup={showSuccessPopup}
                            showCancelPopup={showCancelPopup}
                        />
                    </div>
                </form>
            </Form>
        </>
    );
}
